

def the_wrestlers_and_the_weights(case, data):
    """F15 — Deut 25:11-16 — ONE LINE wrestlers_weights_declared writing wife_seizing_hand_cut_commanded and whole_just_weight_commanded (STATUSES), hand_cutting_pity_barred, diverse_weights_barred and diverse_measures_barred (BLOCKS); the strife by CALL (primeval — 13:7), the strivers and the humiliation's import by CALL (mishpatim — Exodus 21:22), the talion in 'be' and the pity formula by CALL (refuge_war_family — 19:21, 19:13), the substitution operator by CALL (lev24 — 'hand' -> PAY-MONEY), Leviticus 19:35-36's balances by CALL (holiness), the reward clause and the abomination by CALL (covenant_at_horeb, seven_nations); Bava Kamma 8:1, 8:3, Bava Batra 5:10, 5:11 the exam rows"""
    del P_[:]
    ask = case['ask']
    if ask == 'when_men_strive_together_and_the_wife_of_one_draws_near':
        ink('25:11', "'WHEN MEN STRIVE TOGETHER, a man and his brother, AND THE WIFE OF THE ONE DRAWS NEAR to deliver her husband from the hand of him who strikes him, and puts forth her hand and seizes his private parts' — the parser %s at 25:11 ('the one' starred); 25:11 shares %d tokens with Exodus 21:22 (the strivers — 'when men strive'); the strife of 13:7 the spine's citation (292:1 REREAD at Genesis 29's ledger)" % (PARSE[(25, 11)][0], TWIN['25:11 vs Exod 21:22']))
        move("the Sifrei 292:1-4 (read whole at the reading; 292:1 REREAD from Genesis 29's ledger); MISHNAH BAVA KAMMA 8:1, 8:3 (the exam rows, read whole); cold_run_primeval (CALL) — PV.separation(muzzled) = %s; cold_run_mishpatim (CALL) — the F4 HUMILIATION's import of this verse (the module's daemon read: 'IMPORT Deut 25:11-12')" % (PV_MUZZLED[0],), "'when men strive together' — no peace comes out of strife (292:1 — the spine's own citation of Genesis 13:7 again; primeval by CALL); 'the wife of the one draws near to deliver her husband' — the rescuer's license: if she can deliver him by another means she may not seize (292:2-3); 'and seizes his private parts' — the intent to humiliate: he who injures his fellow is liable for five — damage, pain, healing, loss of time, humiliation; humiliation is all according to the humiliator and the humiliated; one who humiliates the naked, the blind, the sleeper is liable; the sleeper who humiliated exempt; he who fell from the roof and injured and humiliated is liable for the damage and exempt from the humiliation, 'AND SHE PUTS FORTH HER HAND AND SEIZES' — he is not liable for humiliation until he intends (Bava Kamma 8:1 — THE VERSE IS THE MISHNAH'S OWN CITATION, the reading's find); the striker of his father and mother without a wound liable for all five; the Hebrew slave's loss of time excepted; the Canaanite slave's humiliation — R. Judah: slaves have no humiliation (Bava Kamma 8:3 — the exam row); THE EXODUS CELL READ THIS VERSE FORWARD — its F4 HUMILIATION pays by 'IMPORT [Deuteronomy 25:11-12, the recorded source in the sugya]' (mishpatim's daemon by CALL)")
        dat("THE PARAMETERS the_five_indemnities (Bava Kamma 8:1 — damage, pain, healing, loss of time, humiliation; the intent required for the humiliation) and the_slaves_humiliation (Bava Kamma 8:3 — R. Judah's arm); the_rescuers_license a DATA row (292:2-3); the seizer's own verdict pays (the body effect reused); the exam's person who fell from the roof and humiliated — the damage paid, the humiliation not, no intent")
        return out("when men strive together and the wife of one draws near (25:11) — no peace out of strife; the rescuer's license; the five indemnities, the humiliation by intent — the verse the Mishnah's own citation; the slave's humiliation R. Judah's; the Exodus cell read this verse forward (the Sifrei 292:1-4; Mishnah Bava Kamma 8:1, 8:3; primeval's %s and mishpatim's import by CALL): the faller from the roof pays the damage, not the humiliation" % (PV_MUZZLED[0],), ['pays'])
    if ask == 'cut_off_her_hand_read_twice':
        ink('25:12', "'YOU SHALL CUT OFF HER HAND, YOUR EYE SHALL NOT PITY' — 'your eye shall not pity' at %s (19:13 the twin; the pity formula's five seats in the book 7:16, 13:9, 19:13, 19:21, 25:12); 25:12 shares %d tokens with 19:21 and %d with 19:13; Onkelos 'you shall cut off her hand, your eye shall not pity' (%s)" % (P('לא', 'תחוס', 'עינך', books=T), TWIN['25:12 vs 19:21'], TWIN['25:12 vs 19:13'], ['ותקוץ', 'ית', 'ידה', 'לא', 'תחוס', 'עינך']))
        move("the Sifrei 293:1-2 (read whole at the reading; 293:2 REREAD from chapters 19-21); cold_run_refuge_war_family (CALL) — RW.the_landmark_and_the_witnesses(the_talion_in_be) = %s; cold_run_lev24 (CALL) — L24.talion(hand) = %s" % (RW_TALION[1], L24_HAND['verdict']), "CUT OFF HER HAND READ TWICE (the reading's find): 293:1 — the rescue: if she can save her husband by another limb, she cuts; if not, 'you shall cut off her hand' — the pursuer's rule on the rescuer; 293:2 — MONEY: 'you shall cut off her hand' — money, by the verbal analogy with 19:21's 'your eye shall not pity' — as there the talion is money, so here (the Sifrei rereading the witnesses' law: refuge_war_family's 'the talion in be' by CALL — 'eye in eye' for 'eye in place of eye', the talion money by Leviticus 24:20's operator; lev24's talion('hand') -> PAY-MONEY, the substitution operator on 'hand'); 'your eye shall not pity' — the pity formula's fifth seat: talion_pity_barred ONE and pity_barred TWO on israel_people THE TAPE'S REFERENCES (SCANS %s) — a new block on the seizing wife's case" % (SCANS['talion_pity_barred'],))
        dat("THE WRITES wife_seizing_hand_cut_commanded (a STATUS — THE PARAMETER the_hands_value, money by 19:21's operator: the hand's worth by the slave-market assessment) and hand_cutting_pity_barred (a BLOCK) on israel_people at the chapters' own day (DK2); the_two_readings a DATA row (the rescue and the money — 293:1-2); the exam's person the seizing wife — pays the hand's value, her hand kept")
        return out("cut off her hand read twice (25:12) — the rescue by another limb, and money by 19:21's verbal analogy: the talion in be, Leviticus 24:20's operator on the hand; the pity formula's fifth seat (the Sifrei 293:1-2; refuge_war_family's %s and lev24's %s by CALL): THE WRITES wife_seizing_hand_cut_commanded and hand_cutting_pity_barred on Israel at the chapters' own day; the seizing wife pays the hand's value" % (RW_TALION[1][0], L24_HAND['verdict']), ['wife_seizing_hand_cut_commanded', 'hand_cutting_pity_barred'])
    if ask == 'a_stone_and_a_stone_an_ephah_and_an_ephah':
        ink('25:13-14', "'YOU SHALL NOT HAVE IN YOUR BAG A STONE AND A STONE, a great and a small; YOU SHALL NOT HAVE IN YOUR HOUSE A MEASURE (an ephah) AND A MEASURE, a great and a small' — 'a stone and a stone' at %s (Proverbs 20:10, 20:23 the others); 25:13 shares %d token with Leviticus 19:35 (the just balances); Onkelos 'weight' at 25:13 and 25:15, 'measure' at 25:14 and 25:15" % (P('אבן', 'ואבן', books=None), TWIN['25:13 vs Lev 19:35']))
        move("the Sifrei 294:1-4 (read whole at the reading); cold_run_holiness (CALL) — HO.conduct(five_effects) = %s (Leviticus 19:15's judge; 19:35-36's balances the statute — the reference)" % (HO_FIVE[0][:2],), "'a stone and a stone' — a weight and a weight; 'a great and a small' — a great one to buy with and a small one to sell with (294:1-2); 'in your bag' — the weights; 'in your house' — the measures: a measure and a measure, a great and a small (294:3-4 — the_weights_kinds); Leviticus 19:35-36's 'just balances, just weights, a just ephah and a just hin' the Sinai seat (holiness' statute — its five effects the judge's; the balances' row named, no cell ask: a REFERENCE)")
        dat("THE WRITES diverse_weights_barred and diverse_measures_barred — BLOCKS on israel_people at the chapters' own day (DK2); the_weights_kinds a DATA row (the great to buy, the small to sell — 294:1-4); the exam's person who keeps a great weight for buying and a small for selling — barred, both stones")
        return out("a stone and a stone, an ephah and an ephah (25:13-14) — the great to buy with and the small to sell with, in the bag and in the house; Leviticus 19:35-36's balances the Sinai seat (the Sifrei 294:1-4; holiness' statute the reference): THE WRITES diverse_weights_barred and diverse_measures_barred, BLOCKS on Israel at the chapters' own day; the two stones barred", ['diverse_weights_barred', 'diverse_measures_barred'])
    if ask == 'a_whole_and_just_weight':
        ink('25:15', "'A WHOLE AND JUST WEIGHT YOU SHALL HAVE, a whole and just measure you shall have, THAT YOUR DAYS MAY BE LONG on the land which the LORD your God gives you' — 25:15 shares %d tokens with 5:16 (%s the shared run — the reward clause's seat; the closest kin %s) and %d with Leviticus 19:36" % (TWIN['25:15 vs 5:16'], SHARED(DV(25, 15), DV(5, 16)), KINC[(25, 15)][:2], TWIN['25:15 vs Lev 19:36']))
        move("the Sifrei 294:5, 295:1-4 (read whole at the reading — 295 headless, on 25:15); cold_run_covenant_at_horeb (CALL) — CH.DATA[the_reward_clause] read; cold_run_seven_nations (CALL) — SN.the_images_and_the_devoted(abomination_to_the_lord) = %s" % (SN_ABOM[1],), "'a whole and just weight' — the whole against the diminished, the just against the false (294:5); 'that your days may be long on the land' — the reward clause's seat: 25:15's land formula a run of seven words with 5:16's (the reading's find 9; blessings_for_hearing TWO on israel_people THE TAPE'S REFERENCE — SCANS %s); 'for an abomination to the LORD your God is everyone who does these, everyone who does unrighteously' (25:16) — the formula's eighth seat, 22:5's run of seven words: the weights' reward and the false measure's sin like the forbidden unions' (295:1-4 — the_abomination_of_the_weights; seven_nations by CALL)" % (SCANS['blessings_for_hearing'],))
        dat("THE WRITE whole_just_weight_commanded — a STATUS on israel_people at the chapters' own day (DK2); the_abomination_of_the_weights a DATA row (295:1-4 — the false measure's sin like the unions'); blessings_for_hearing the reference, no third write; the exam's person who keeps his weight whole and just — accepted, his days long")
        return out("a whole and just weight (25:15) — the whole against the diminished, the just against the false; the reward clause 5:16's run of seven; the abomination's eighth seat at 25:16 (the Sifrei 294:5, 295:1-4; covenant_at_horeb's clause and seven_nations' %s by CALL): THE WRITE whole_just_weight_commanded, a STATUS on Israel at the chapters' own day; the just weigher accepted" % (SN_ABOM[1][0],), ['whole_just_weight_commanded'])
    if ask == 'the_local_custom_and_the_inspector':
        ink('25:14-15', "'a MEASURE and a measure … a whole and just MEASURE' — the measures' custom the answer sheet's parameter (Bava Batra 5:10-11 the exam rows); the Mishnah by abbreviation at 294:8, the English supplying (the reading's find)")
        move("the Sifrei 294:6-8 (read whole at the reading); MISHNAH BAVA BATRA 5:10, 5:11 (the exam rows, read whole)", "THE LOCAL CUSTOM BINDING EVEN TO THE BUYER'S GAIN — where they measure small one may not measure large, where they level one may not heap: the custom of the place (294:6-7 — the reading's find; Bava Batra 5:11: the seller gives the extra handbreadth, the one-tenth for liquids and the one-twentieth for dry goods, the custom of the place); THE MARKET INSPECTOR AGRONOMOS — the Greek: the inspectors appointed over the measures, not over the prices — Rabban Shimon b. Gamliel (294:8 — the Mishnah by abbreviation, the English supplying Bava Batra 5:10: the wholesaler cleans his measures once in thirty days, the householder once in twelve months — Rabban Shimon b. Gamliel reversed; the shopkeeper twice a week, wipes his weights once a week, cleans the scales at every weighing — the cleaning clocks)")
        dat("THE PARAMETERS the_local_custom (Bava Batra 5:11 — the custom of the place binding, the extra handbreadth, the tenth and the twentieth) and the_cleaning_clocks (Bava Batra 5:10 — thirty days, twelve months reversed, twice a week: two arms); the_market_inspector a DATA row (the agronomos — the Greek, 294:8); the exam's person who heaps where they level — barred by the custom, even to the buyer's gain")
        return out("the local custom and the inspector (25:14-15) — the custom of the place binding even to the buyer's gain; the extra handbreadth, the tenth and the twentieth; the inspectors over the measures; the cleaning clocks two arms (the Sifrei 294:6-8; Mishnah Bava Batra 5:10, 5:11): the heaper where they level barred", ['accepted'])
    return 'no verdict in span', [], list(P_)


def amalek(case, data):
    """F16 — Deut 25:17-19 — ONE LINE amalek_remembrance_declared writing amalek_remembrance_commanded and amalek_memory_blotting_commanded (STATUSES) and amalek_forgetting_barred (a BLOCK); Exodus 17:8-16's Amalek by CALL (exodus_story — the blotting a HEAVEN entry open to this chapter), 17:14's king by CALL (courts_prophet — the three on entering), 8:11's forgetting the reference; 1 Samuel 15 THE POINTER AHEAD owed"""
    del P_[:]
    ask = case['ask']
    if ask == 'remember_what_amalek_did_to_you':
        ink('25:17', "'REMEMBER WHAT AMALEK DID TO YOU in the way when you came out of Egypt' — 'remember' the infinitive absolute (24:9's twin — %s); 'in the way when you came out of Egypt' the three remembrances' one phrase %s; 25:17 shares %d tokens with 24:9 and %d with Exodus 17:8 (Amalek's coming — the tape's own act); Onkelos 'Amalek' at 25:17 and 25:19" % ([(c, v, x) for c, v in SPAN for x in W(c, v) if x == 'זכור'], P('בדרך', 'בצאתכם', 'ממצרים', books=T), TWIN['24:9 vs 25:17'], TWIN['25:17 vs Exod 17:8']))
        move("the Sifrei 296:1 (read whole at the reading); cold_run_exodus_story (CALL) — ES.amalek(weakened_seat) = %s, ES.amalek(blotting) = %s" % (ES_WEAK[0], ES_BLOT[0]), "'remember' — with the mouth; 'you shall not forget' (25:19) — in the heart (296:1, 296:9 — the two organs); 'what Amalek did to you' — the tape's own act at Exodus 17:8: amalek_came the readback's REFERENCE, a retelling never a second act; 'and Joshua weakened Amalek' the verb's one Torah seat (exodus_story's weakened_seat by CALL: amalek_weakened ONE on amaleq — SCANS %s)" % (SCANS['amalek_weakened'],))
        dat("THE WRITE amalek_remembrance_commanded — a STATUS on israel_people at the chapters' own day (DK2); the_remembrances_two_organs a DATA row (the mouth and the heart — 296:1, 296:9); the exam's person who reads 25:17 as a new coming of Amalek — the tape's one act, remembered")
        return out("remember what Amalek did to you (25:17) — with the mouth; the three remembrances' one phrase; the tape's own act at Exodus 17:8 remembered, never a second (the Sifrei 296:1; exodus_story's %s by CALL): THE WRITE amalek_remembrance_commanded, a STATUS on Israel at the chapters' own day; no second coming" % (ES_WEAK[2][0],), ['amalek_remembrance_commanded'])
    if ask == 'how_he_met_you':
        ink('25:18', "'how HE MET YOU in the way and cut off your rear, all the stragglers behind you, when you were faint and weary, AND HE FEARED NOT GOD' — the one 'God' of the four chapters (%s — the reading's find 14); the wayyiqtol (the narrative verb form) 'and he cut off' at 25:18 (%s); Onkelos 'the stragglers'" % ([(v, x) for v in range(1, 20) for x in W25(v) if x in ('אלהיו', 'אלהי', 'אלהים', 'אלהיכם')], [(c, v, x) for c, v in SPAN for x, m in MO[(c, v)] if m and re.search(r'V[a-zA-Z]w', m) and c == 25]))
        move("the Sifrei 296:2-4 (read whole at the reading); Onkelos 25:18", "'how he met you' — three readings of one consonantal word: by chance (the way of the world), by cooling (he cooled you before the nations — the bath that all feared to enter until one leapt in), by nocturnal uncleanness (he defiled you with the night's chance — 23:11's word) (296:2-3 — the_meetings_readings: the three homographs); 'and cut off your rear' — the stragglers: those the cloud cast out (296:4 — Onkelos 'the stragglers'); 'and he feared not God' — Amalek's charge, the one 'God' of the four chapters")
        dat("the_meetings_readings a DATA row (the chance, the cooling, the uncleanness — the three homographs of 296:2-3); the exam's person who reads 'met you' as the night's chance — the third homograph, 23:11's word")
        return out("how he met you (25:18) — by chance, by cooling, by the night's uncleanness: three readings of one word; the stragglers cut off; he feared not God — the one God of the four chapters (the Sifrei 296:2-4; Onkelos): the three homographs a data row", ['accepted'])
    if ask == 'when_the_lord_gives_you_rest':
        ink('25:19', "'And it shall be, WHEN THE LORD YOUR GOD GIVES YOU REST from all your enemies around, in the land which the LORD your God gives you FOR AN INHERITANCE TO POSSESS IT, YOU SHALL BLOT OUT THE MEMORY OF AMALEK FROM UNDER HEAVEN' — the gift formula at %s (15:4 and 25:19 the two 'for an inheritance to possess it' — %s); 'from under heaven' at %s (Exodus 17:14's the twin — 25:19 shares %d tokens with it, %s the shared run); 25:19 shares %d tokens with 1 Samuel 15:2 (the run ahead)" % (P('נתן', 'לך', 'נחלה', books=T), P('נחלה', 'לרשתה', books=T), P('מתחת', 'השמים', books=T), TWIN['25:19 vs Exod 17:14'], SHARED(DV(25, 19), ('Exod', 17, 14)), TWIN['25:19 vs 1Sam 15:2']))
        move("the Sifrei 296:5-8 (read whole at the reading); cold_run_exodus_story (CALL) — ES.amalek(blotting) = %s ('a HEAVEN entry on Amalek OPEN at the three books' end: Deut 25:19's command and 1 Sam 15's run are book-bound'); cold_run_courts_prophet (CALL) — 17:14's king (CP.the_king read: %s)" % (ES_BLOT[0], CP_HIRE[1]), "'when the LORD your God gives you rest' — THREE COMMANDMENTS ON ENTERING THE LAND: to appoint a king, to blot out Amalek, to build the chosen house — in this order (296:5-6 — the_three_on_entering; courts_prophet's king 17:14's 'when you come into the land'); 'from all your enemies around' — the rest 1 Samuel 15's clock: Saul's war the run's citation AHEAD — A POINTER OWED (296:7); 'in the land … for an inheritance to possess it' — the gift formula's seat, 15:4's twin (the reading's find 9); 'you shall blot out the memory of Amalek from under heaven' — the command on ISRAEL written here; Exodus 17:14's 'I will surely blot out' the LORD's oath — amalek_to_be_blotted ONE on amaleq THE TAPE'S REFERENCE, the heaven entry OPEN (exodus_story's blotting by CALL: book-bound to this command and Samuel's run; SCANS %s); blotting_sworn at 17:14-16 the readback's REFERENCE; THE TWO BLOTTINGS — Amalek's memory here, the dead brother's name at 25:6 (296:9 — the reading's find)" % (SCANS['amalek_to_be_blotted'],))
        dat("THE WRITE amalek_memory_blotting_commanded — a STATUS on israel_people at the chapters' own day (DK2); the_three_on_entering a DATA row (the king, Amalek, the house — 296:5-6); the pointer 25:19 -> 1 Samuel 15 OWED (no pointer row this sitting); amalek_to_be_blotted the reference — the LORD's oath open, Israel's command written here; the exam's person who blots Amalek before the king is set — the order's parameter, the sages' order the king first")
        return out("when the LORD gives you rest (25:19) — the three on entering: the king, Amalek, the house; the rest Samuel's clock, the run ahead a pointer owed; the gift formula 15:4's twin; the command on Israel written where the LORD's oath stands open (the Sifrei 296:5-8; exodus_story's %s and courts_prophet's king by CALL): THE WRITE amalek_memory_blotting_commanded, a STATUS on Israel at the chapters' own day; the order the king first" % (ES_BLOT[0],), ['amalek_memory_blotting_commanded'])
    if ask == 'you_shall_not_forget':
        ink('25:19', "'YOU SHALL NOT FORGET' — twice in the Torah (%s — 25:19 and 31:21, the reading's find 10); forgetting_barred ONE on israel_people (8:11's line) THE TAPE'S REFERENCE (SCANS %s); 25:19 shares %d tokens with 8:11" % (P('לא', 'תשכח', books=T), SCANS['forgetting_barred'], TWIN['25:19 vs 8:11']))
        move("the Sifrei 296:9 (read whole at the reading); the tape's forgetting_warned at Deut 8:11 (the readback's REFERENCE — 8:11's block the formula's first seat)", "'you shall not forget' — in the heart; 'remember' — with the mouth: the two organs (296:9 — the two blottings beside them: the memory of Amalek from under heaven, and the name of the dead brother from Israel at 25:6 — 'not blotted out' the verb's other seat in the four chapters); 8:11's 'take heed lest you forget the LORD your God' — forgetting_barred ONE on israel_people, the formula's first seat: THIS a new BLOCK on Amalek's memory, not a second write of 8:11's")
        dat("THE WRITE amalek_forgetting_barred — a BLOCK on israel_people at the chapters' own day (DK2); the_two_blottings a DATA row (Amalek's memory, the brother's name — 296:9); forgetting_barred 8:11's the reference; the exam's person who remembers with the mouth and forgets in the heart — the block on the heart's forgetting")
        return out("you shall not forget (25:19) — in the heart, beside the mouth's remembering; the two blottings, Amalek's memory and the brother's name; twice in the Torah, 8:11's forgetting the reference (the Sifrei 296:9): THE WRITE amalek_forgetting_barred, a BLOCK on Israel at the chapters' own day; the heart's forgetting barred", ['amalek_forgetting_barred'])
    return 'no verdict in span', [], list(P_)
